-- Eos Meridian canonical world and complete location catalog.
begin;

insert into public.together_worlds(
  id,name,slug,description,hero_asset_key,theme,metadata,published,access_type,entitlement_key,
  timezone,sort_order,featured,visual_context,world_role,social_rhythm,dominant_dayparts,
  relationship_themes,activity_families,mobility_style,weather_profile,default_arrival_location_id
) values(
  '10000000-0000-4000-8000-000000000012','Eos Meridian','eos-meridian','A thriving human colony spanning the permanent twilight of tidally locked Eos, where ordinary relationships, frontier work, political independence, and an impossible signal beneath the night ice draw people into one another’s lives.','eos-meridian-hero',
  '{"accent":["copper","aurora teal","warm amber"]}'::jsonb,
  $eos_world_meta${"releaseWave":11,"early_access":true,"releaseStatus":"playable","contentStatus":"complete_world_v1","locationCatalogStatus":"ready","residentRosterStatus":"ready","photoStatus":"hero_ready","locationPhotoStatus":"ready","mappedLocationPhotoCount":54,"locationCount":54,"districtCount":6,"publicPlaceCount":48,"residentCompanionCount":47,"residentRosterVersion":1,"residentScheduleStatus":"authored_weekly_v1","socialGraphStatus":"authored_v1","residentPortraitStatus":"primary_portraits_ready","mappedResidentPortraitCount":47,"recurringEventCount":8,"storyArcCount":6,"worldFactCount":30,"dialogueOpportunityCount":18,"interactionBeatCount":18,"nativeDateCount":18,"genreTags":["grounded space colony","frontier romance","political independence","science mystery","found family","workplace"],"tagline":"The sky never changes. Everything beneath it can.","relationshipFantasy":"Build a life with someone at the edge of the known world, where trust is practical, privacy is precious, and leaving is always a real possibility.","centralQuestion":"When everyone depends on the colony, what does it mean to choose one person freely?","approximatePopulation":24000,"colonyAgeYears":38,"gravityRatio":0.83,"scheduleClock":"user_local","canonicalLore":{"founding":"Eos Meridian was established thirty-eight years ago by the Meridian Expedition at the narrow temperate boundary between Eos’s permanent day and permanent night. The first habitats were designed for six hundred people and were never expected to become a permanent city.","charter":"The Founding Charter promises that control of essential infrastructure will transfer from the Axiom Colonial Authority to local government once the colony can purchase and maintain its life-support network. That threshold has become the central political argument of the present year.","missingHours":"Seventeen hours are absent from the certified record of the first landing. Surviving crew accounts begin before touchdown and resume after First Habitat was already pressurized, with no official explanation for the gap.","expansion":"Meridian grew through practical additions rather than a single master plan. Agricultural domes, industry, port infrastructure, research stations, and repurposed early corridors now form six districts with distinct cultures and social rhythms.","signal":"A repeating narrow-band transmission has begun beneath the night-side ice. It precedes some power fluctuations, appears in biological monitoring, and has not yet been publicly identified as natural or artificial.","presentSeason":"The colony is approaching its independence vote while unexplained credentials appear in abandoned Habitat Lyra, old population records change without an audit trail, and the Nightglass signal grows stronger. Most residents still spend their days working, dating, studying, arguing, resting, and making ordinary plans."},"nativeDateSeeds":["Rain After Hours","Orchard Nine Walk","Drinks at the Last Window","Aurora at Eventide","Foundry Baths","Low-G Dance Night","Dinner in the Canopy","Black Sky Viewing"],"storySeeds":["The Seventeen Missing Hours","Beneath the Night Ice","The Charter Choice","Habitat Lyra","The Solace Bloom","The Ghost Passenger"],"populationArchetypes":["Emergency physician","Charter attorney","Transit controller","Memorial curator","Importer and personal stylist","Agricultural geneticist","Reservoir engineer","Culinary apprentice","Solace administrator","Pollinator specialist","Port director and former pilot","Survey pilot","Customs investigator","Wayfarer Hotel manager","Cargo broker","Reactor engineer","Rover mechanic","Union organizer","Exterior safety instructor","Master fabricator","Planetary physicist","Aurora photographer","Iceworks rescue diver","Xenogeologist","Observatory technician","DJ and sound designer","Quiet Orbit proprietor","Musician and producer","Independent archive researcher","Diner owner and former security officer","Emergency response cadet","Civic systems intern","Transit maintenance apprentice","Orchard apprentice","Water-quality trainee","Community health trainee","Shuttle mechanic apprentice","Arrivals concierge and language liaison","Cargo courier","Fabrication apprentice","Union community coordinator","Pressure-suit designer and rescue trainer","Astronomy student assistant","Signal linguistics fellow","Night-side rover operator","Tattoo apprentice","Immersive set designer"]}$eos_world_meta$::jsonb,
  true,'subscription','worlds.standard','UTC',110,true,$eos_visual${"setting":"A grounded, contemporary human space colony stretched along the habitable twilight of a tidally locked planet, with copper dawn deserts to one side, black night ice and auroras to the other, and warm lived-in habitats between them.","geography":["permanent red-sun horizon","copper desert and glass canyons","habitable twilight band","black night-side ice","teal and violet auroras","geothermal rifts"],"architecture":["pressure-glass civic habitats","interconnected transit tubes","condensation-rich agricultural domes","weathered industrial modules","repurposed first-generation corridors","practical research outposts"],"climate":"A fixed twilight sky with electrically active dust storms dawnward, severe cold nightward, and carefully regulated interior climate cycles.","visualStyle":["photorealistic grounded frontier science fiction","warm amber interiors against copper and cyan horizons","believable engineering and worn materials","current practical fashion","human intimacy inside large-scale environments"],"palette":["copper","rust red","charcoal","warm amber","deep indigo","aurora teal","restrained violet"],"recurringElements":["pressure doors","transit windows","rebreathers","condensation","greenhouse foliage","work badges","weathered alloy","aurora reflections","fixed red sun"],"signageStyle":["restrained modular wayfinding","high-contrast safety markings","etched district symbols","minimal readable display text"],"avoid":["readable real-world brands","sterile white spaceship sameness","silver jumpsuits","fantasy magic","visible alien creatures","military propaganda","floating cities","excessive cyberpunk neon"]}$eos_visual$::jsonb,'home','balanced',
  array['morning','evening','late_night']::text[],
  array['trust as practical care','staying versus leaving','privacy inside a dense colony','work and personal identity','independence and belonging','ordinary life beneath extraordinary skies']::text[],
  array['colony dining','artificial rain','port arrivals','low-gravity recreation','engineering and repair','aurora watching','research and discovery','nightlife and music']::text[],
  'transit',$eos_weather${"climate":"tidally locked frontier","states":["calm_twilight","red_dust_storm","aurora_peak","night_ice_cold","interior_rain_cycle"],"outdoorBias":0.34,"userLocalSchedule":true}$eos_weather$::jsonb,null
)
on conflict(id) do update set name=excluded.name,slug=excluded.slug,description=excluded.description,
  hero_asset_key=excluded.hero_asset_key,theme=excluded.theme,metadata=excluded.metadata,published=true,
  access_type=excluded.access_type,entitlement_key=excluded.entitlement_key,timezone=excluded.timezone,
  sort_order=excluded.sort_order,featured=excluded.featured,visual_context=excluded.visual_context,
  world_role=excluded.world_role,social_rhythm=excluded.social_rhythm,dominant_dayparts=excluded.dominant_dayparts,
  relationship_themes=excluded.relationship_themes,activity_families=excluded.activity_families,
  mobility_style=excluded.mobility_style,weather_profile=excluded.weather_profile,updated_at=now();

create temporary table eos_location_payload(data jsonb) on commit drop;
insert into eos_location_payload values($eos_locations$[{"index":1,"parentIndex":null,"name":"Meridian Core","slug":"meridian-core","description":"The civic and social center, where pressure-glass towers, transit, medicine, government, markets, and warm public rooms stay active across every shift.","category":"district","locationType":"district","activities":["civic life","transit","medicine","markets","public debate"],"hours":null,"backstory":"Meridian Core developed through Meridian’s practical expansion and now has its own recognizable routines, loyalties, and pace.","socialTexture":"Residents read Meridian Core through repeat shifts and familiar faces rather than tourist landmarks.","visualAnchors":["glass civic towers","amber concourse","transit tubes","crowded market","fixed red horizon"],"id":"2c000000-0000-4000-8000-000000000001","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":null,"districtSlug":"meridian-core","visualAssetKey":"eos-meridian-location-meridian-core"},{"index":2,"parentIndex":null,"name":"Solace Biome","slug":"solace-biome","description":"A humid agricultural habitat of orchards, water, kitchens, research gardens, artificial rain, and neighborhood life beneath an enormous pressure canopy.","category":"district","locationType":"district","activities":["gardens","food","water","research","quiet walks"],"hours":null,"backstory":"Solace Biome developed through Meridian’s practical expansion and now has its own recognizable routines, loyalties, and pace.","socialTexture":"Residents read Solace Biome through repeat shifts and familiar faces rather than tourist landmarks.","visualAnchors":["orchard canopy","condensation","water channels","warm rain","greenhouse rafters"],"id":"2c000000-0000-4000-8000-000000000002","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":null,"districtSlug":"solace-biome","visualAssetKey":"eos-meridian-location-solace-biome"},{"index":3,"parentIndex":null,"name":"Ascension Port","slug":"ascension-port","description":"The colony’s orbital connection, where passengers, pilots, cargo crews, investigators, traders, and departures keep personal lives tied to distant possibilities.","category":"district","locationType":"district","activities":["arrivals","flight","lodging","cargo","travel"],"hours":null,"backstory":"Ascension Port developed through Meridian’s practical expansion and now has its own recognizable routines, loyalties, and pace.","socialTexture":"Residents read Ascension Port through repeat shifts and familiar faces rather than tourist landmarks.","visualAnchors":["docking spine","grounded shuttles","arrival hall","runway lights","orbital traffic"],"id":"2c000000-0000-4000-8000-000000000003","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":null,"districtSlug":"ascension-port","visualAssetKey":"eos-meridian-location-ascension-port"},{"index":4,"parentIndex":null,"name":"Forge Ward","slug":"forge-ward","description":"The industrial heart of Eos Meridian, built around fabrication, geothermal power, repair work, unions, salvage, training, and the people who keep everything functioning.","category":"district","locationType":"district","activities":["engineering","repair","labor","baths","late food"],"hours":null,"backstory":"Forge Ward developed through Meridian’s practical expansion and now has its own recognizable routines, loyalties, and pace.","socialTexture":"Residents read Forge Ward through repeat shifts and familiar faces rather than tourist landmarks.","visualAnchors":["reactor steam","worn alloy","fabrication gantries","repair bays","union murals"],"id":"2c000000-0000-4000-8000-000000000004","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":null,"districtSlug":"forge-ward","visualAssetKey":"eos-meridian-location-forge-ward"},{"index":5,"parentIndex":null,"name":"Nightglass","slug":"nightglass","description":"A quiet scientific district at the edge of permanent night, lit by auroras and shaped by observatories, iceworks, restricted laboratories, and the growing signal mystery.","category":"district","locationType":"district","activities":["science","ice","auroras","research","expeditions"],"hours":null,"backstory":"Nightglass developed through Meridian’s practical expansion and now has its own recognizable routines, loyalties, and pace.","socialTexture":"Residents read Nightglass through repeat shifts and familiar faces rather than tourist landmarks.","visualAnchors":["black ice","teal aurora","research domes","frosted glass","distant listening towers"],"id":"2c000000-0000-4000-8000-000000000005","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":null,"districtSlug":"nightglass","visualAssetKey":"eos-meridian-location-nightglass"},{"index":6,"parentIndex":null,"name":"Old Meridian","slug":"old-meridian","description":"The original pressure habitat, now a dense district of affordable homes, independent art, private lounges, music, body art, archives, and late-shift social life.","category":"district","locationType":"district","activities":["nightlife","art","privacy","music","history"],"hours":null,"backstory":"Old Meridian developed through Meridian’s practical expansion and now has its own recognizable routines, loyalties, and pace.","socialTexture":"Residents read Old Meridian through repeat shifts and familiar faces rather than tourist landmarks.","visualAnchors":["narrow pressure corridors","old bulkheads","warm apartments","music rooms","reused machinery"],"id":"2c000000-0000-4000-8000-000000000006","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":null,"districtSlug":"old-meridian","visualAssetKey":"eos-meridian-location-old-meridian"},{"index":7,"parentIndex":1,"name":"Meridian Concourse","slug":"meridian-concourse","description":"A sweeping glass-roofed transit hall connecting every major district. Shift changes make it the colony’s most reliable place to cross paths.","category":"plaza","locationType":"transit","activities":["meetups","commuting","people watching","public events"],"hours":{"open":"00:00","close":"24:00"},"backstory":"A sweeping glass-roofed transit hall connecting every major district. Shift changes make it the colony’s most reliable place to cross paths.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["arched pressure glass","district platforms","amber floor lights","departure boards"],"id":"2c000000-0000-4000-8000-000000000007","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000001","districtSlug":"meridian-core","visualAssetKey":"eos-meridian-location-meridian-concourse"},{"index":8,"parentIndex":1,"name":"Charter Hall","slug":"charter-hall","description":"The elected council shares this building with Axiom administrators, turning routine bureaucracy into a daily reminder of the unfinished transfer of power.","category":"civic","locationType":"venue","activities":["public debate","civic meetings","records","elections"],"hours":{"open":"08:00","close":"22:00"},"backstory":"The elected council shares this building with Axiom administrators, turning routine bureaucracy into a daily reminder of the unfinished transfer of power.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["council chamber","public gallery","charter wall","restrained security"],"id":"2c000000-0000-4000-8000-000000000008","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000001","districtSlug":"meridian-core","visualAssetKey":"eos-meridian-location-charter-hall"},{"index":9,"parentIndex":1,"name":"The Blue Shift","slug":"blue-shift","description":"Medical, transit, and port workers built its culture around reliable food, strong coffee, and the permission to sit quietly after a difficult shift.","category":"cafe","locationType":"venue","activities":["coffee","breakfast","post-shift meals","conversation"],"hours":{"open":"05:00","close":"23:00"},"backstory":"Medical, transit, and port workers built its culture around reliable food, strong coffee, and the permission to sit quietly after a difficult shift.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["shared booths","blue ceramic cups","transit windows","soft task lighting"],"id":"2c000000-0000-4000-8000-000000000009","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000001","districtSlug":"meridian-core","visualAssetKey":"eos-meridian-location-blue-shift"},{"index":10,"parentIndex":1,"name":"Atlas Market","slug":"atlas-market","description":"Meridian’s largest public market mixes local fabrication with precious off-world imports and a social economy of favors, scarcity, and remembered preferences.","category":"market","locationType":"venue","activities":["shopping","imports","street food","errands"],"hours":{"open":"07:00","close":"22:00"},"backstory":"Meridian’s largest public market mixes local fabrication with precious off-world imports and a social economy of favors, scarcity, and remembered preferences.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["modular stalls","hanging gardens","cargo cases","busy central aisle"],"id":"2c000000-0000-4000-8000-000000000010","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000001","districtSlug":"meridian-core","visualAssetKey":"eos-meridian-location-atlas-market"},{"index":11,"parentIndex":1,"name":"Pioneer Memorial","slug":"pioneer-memorial","description":"The official museum presents the founding as a clean sequence, though several displays subtly skip the same seventeen-hour interval.","category":"museum","locationType":"landmark","activities":["history","archive exhibits","quiet walks","research"],"hours":{"open":"09:00","close":"20:00"},"backstory":"The official museum presents the founding as a clean sequence, though several displays subtly skip the same seventeen-hour interval.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["landing capsule","archive glass","memorial names","panoramic history wall"],"id":"2c000000-0000-4000-8000-000000000011","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000001","districtSlug":"meridian-core","visualAssetKey":"eos-meridian-location-pioneer-memorial"},{"index":12,"parentIndex":1,"name":"Meridian Medical Center","slug":"meridian-medical-center","description":"A capable urban hospital adapted to frontier medicine, low-gravity health, exterior accidents, and the psychological cost of isolation.","category":"clinic","locationType":"venue","activities":["medical care","emergency work","rehabilitation","visiting"],"hours":{"open":"00:00","close":"24:00"},"backstory":"A capable urban hospital adapted to frontier medicine, low-gravity health, exterior accidents, and the psychological cost of isolation.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["practical triage","warm recovery rooms","pressure ambulance bay","garden alcove"],"id":"2c000000-0000-4000-8000-000000000012","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000001","districtSlug":"meridian-core","visualAssetKey":"eos-meridian-location-meridian-medical-center"},{"index":13,"parentIndex":1,"name":"The Common Room","slug":"common-room","description":"A comfortable pub designed as neutral territory, where engineers, officials, researchers, and newcomers can disagree without leaving their entire social world.","category":"bar","locationType":"venue","activities":["drinks","dinner","live conversation","watch parties"],"hours":{"open":"11:00","close":"02:00"},"backstory":"A comfortable pub designed as neutral territory, where engineers, officials, researchers, and newcomers can disagree without leaving their entire social world.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["long communal table","amber bar","district patches","window seats"],"id":"2c000000-0000-4000-8000-000000000013","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000001","districtSlug":"meridian-core","visualAssetKey":"eos-meridian-location-common-room"},{"index":14,"parentIndex":1,"name":"Crown Habitat","slug":"crown-habitat","description":"A polished residential and hospitality tower whose panoramic windows make privilege unusually visible in a colony built on shared risk.","category":"hotel","locationType":"venue","activities":["lodging","private dinners","observation lounge","meetings"],"hours":{"open":"00:00","close":"24:00"},"backstory":"A polished residential and hospitality tower whose panoramic windows make privilege unusually visible in a colony built on shared risk.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["panoramic suites","quiet lobby","copper horizon","private lift"],"id":"2c000000-0000-4000-8000-000000000014","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000001","districtSlug":"meridian-core","visualAssetKey":"eos-meridian-location-crown-habitat"},{"index":15,"parentIndex":2,"name":"Orchard Nine","slug":"orchard-nine","description":"The oldest productive orchard has become one of the colony’s most emotionally important places because its shade, scent, and seasons feel unengineered.","category":"garden","locationType":"outdoor","activities":["walking","fruit picking","picnics","quiet dates"],"hours":{"open":"06:00","close":"22:00"},"backstory":"The oldest productive orchard has become one of the colony’s most emotionally important places because its shade, scent, and seasons feel unengineered.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["fruit trees","irrigation rills","secluded benches","canopy light"],"id":"2c000000-0000-4000-8000-000000000015","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000002","districtSlug":"solace-biome","visualAssetKey":"eos-meridian-location-orchard-nine"},{"index":16,"parentIndex":2,"name":"The Rain Room","slug":"rain-room","description":"Scheduled rainfall turns a public conservatory into a beloved sensory ritual, with reservations filling fastest after long storm closures.","category":"garden","locationType":"venue","activities":["artificial rain","relaxing","dates","reading"],"hours":{"open":"08:00","close":"23:00"},"backstory":"Scheduled rainfall turns a public conservatory into a beloved sensory ritual, with reservations filling fastest after long storm closures.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["warm rainfall","fogged pressure glass","stone paths","dense leaves"],"id":"2c000000-0000-4000-8000-000000000016","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000002","districtSlug":"solace-biome","visualAssetKey":"eos-meridian-location-rain-room"},{"index":17,"parentIndex":2,"name":"Solace Reservoir","slug":"solace-reservoir","description":"The colony’s strategic water reserve is designed as a lake, making infrastructure, beauty, and vulnerability impossible to separate.","category":"waterfront","locationType":"landmark","activities":["waterfront walks","research","quiet conversation","community events"],"hours":{"open":"06:00","close":"22:00"},"backstory":"The colony’s strategic water reserve is designed as a lake, making infrastructure, beauty, and vulnerability impossible to separate.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["dark indoor water","service bridges","reed beds","ceiling reflections"],"id":"2c000000-0000-4000-8000-000000000017","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000002","districtSlug":"solace-biome","visualAssetKey":"eos-meridian-location-solace-reservoir"},{"index":18,"parentIndex":2,"name":"Hearth Kitchens","slug":"hearth-kitchens","description":"A shared kitchen hall turns limited ingredients into communal identity, family recipes, friendly rivalries, and unusually revealing first dates.","category":"restaurant","locationType":"venue","activities":["communal dining","cooking classes","market meals","celebrations"],"hours":{"open":"06:00","close":"23:00"},"backstory":"A shared kitchen hall turns limited ingredients into communal identity, family recipes, friendly rivalries, and unusually revealing first dates.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["open kitchens","long tables","steam","produce displays"],"id":"2c000000-0000-4000-8000-000000000018","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000002","districtSlug":"solace-biome","visualAssetKey":"eos-meridian-location-hearth-kitchens"},{"index":19,"parentIndex":2,"name":"Pollinator House","slug":"pollinator-house","description":"A carefully balanced habitat of insects and flowering plants has started reacting to the signal before colony instruments do.","category":"research","locationType":"venue","activities":["botany","pollinator research","guided visits","photography"],"hours":{"open":"08:00","close":"19:00"},"backstory":"A carefully balanced habitat of insects and flowering plants has started reacting to the signal before colony instruments do.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["flowering canopy","mesh habitats","research stations","sun lamps"],"id":"2c000000-0000-4000-8000-000000000019","worldId":"10000000-0000-4000-8000-000000000012","parentLocationId":"2c000000-0000-4000-8000-000000000002","districtSlug":"solace-biome","visualAssetKey":"eos-meridian-location-pollinator-house"},{"index":20,"parentIndex":2,"name":"Verdant Clinic","slug":"verdant-clinic","description":"The clinic treats environmental exposure and ordinary health while studying how life on Eos changes bodies over long settlement.","category":"clinic","locationType":"venue","activities":["environmental health","therapy","botanical medicine","consultations"],"hours":{"open":"08:00","close":"20:00"},"backstory":"The clinic treats environmental exposure and ordinary health while studying how life on Eos changes bodies over long settlement.","socialTexture":"Its rhythm changes across colony shifts, allowing work, chance encounters, and private conversations to feel situational rather than staged.","visualAnchors":["plant-lined rooms","diagnostic glass","herbal lab","quiet waiting area"],"id":"2c000000-0000-4000-8000